(4583057, 661425, 18563, '<td valign="top">I love this one! Well done!</td>', 'I love this one! Well done!', '2008-03-24 10:18:26.000000', NULL, 1),
(4583060, 661383, 65234, '<td valign="top">You let him warn them?  And he''s crying.  I believe the kinder thing is just eat the entire Peep in one bite, out of sight of the rest, so all they know is he''s gone to another place and he doesn''t suffer too long.  After viewing entries like this I am becoming Convinced we need a Society for the Prevention of Cruelty to Peeps!</td>', 'You let him warn them?  And he''s crying.  I believe the kinder thing is just eat the entire Peep in one bite, out of sight of the rest, so all they know is he''s gone to another place and he doesn''t suffer too long.  After viewing entries like this I am becoming Convinced we need a Society for the Prevention of Cruelty to Peeps!', '2008-03-24 10:19:31.000000', NULL, 1),
