(4588948, 661429, 83313, '<td valign="top">His family looks very proud.</td>', 'His family looks very proud.', '2008-03-26 13:23:53.000000', NULL, 1),
(4588950, 661478, 27373, '<td valign="top">Mistress Peep?</td>', 'Mistress Peep?', '2008-03-26 13:24:02.000000', NULL, 1),
(4588951, 661521, 27373, '<td valign="top">You get a 10 just for doing this much setup on a 24 hour challenge</td>', 'You get a 10 just for doing this much setup on a 24 hour challenge', '2008-03-26 13:24:32.000000', NULL, 1),
(4588956, 661291, 83313, '<td valign="top">Not too far off from my own original idea, but I was not able to find the G.I. Joe or Elmer Fudd I needed to be a hunter.</td>', 'Not too far off from my own original idea, but I was not able to find the G.I. Joe or Elmer Fudd I needed to be a hunter.', '2008-03-26 13:25:22.000000', NULL, 1),
(4588958, 661242, 83313, '<td valign="top">Very good idea.</td>', 'Very good idea.', '2008-03-26 13:25:55.000000', NULL, 1),
(4588962, 661328, 83313, '<td valign="top">A peace offering? Kitty looks disinterested.</td>', 'A peace offering? Kitty looks disinterested.', '2008-03-26 13:27:06.000000', NULL, 1),
(4588964, 661498, 83313, '<td valign="top">Needs a little more depth of field and I don''t think the b/w worked well here.</td>', 'Needs a little more depth of field and I don''t think the b/w worked well here.', '2008-03-26 13:27:54.000000', NULL, 1),
(4588965, 661263, 83313, '<td valign="top">Just a basic crowd of peeps, but decently done. Lighting could have been a little better to bring out the details, but still pretty good.</td>', 'Just a basic crowd of peeps, but decently done. Lighting could have been a little better to bring out the details, but still pretty good.', '2008-03-26 13:29:02.000000', NULL, 1),
(4588972, 661112, 83313, '<td valign="top">I never knew before this that there were so many ways to destroy a peep. This one is simple, but effectively done.</td>', 'I never knew before this that there were so many ways to destroy a peep. This one is simple, but effectively done.', '2008-03-26 13:30:08.000000', NULL, 1),
(4588974, 661293, 83313, '<td valign="top">The little lovebirds!</td>', 'The little lovebirds!', '2008-03-26 13:30:47.000000', NULL, 1),
(4588976, 661184, 83313, '<td valign="top">Oh, cool!</td>', 'Oh, cool!', '2008-03-26 13:31:17.000000', NULL, 1),
