(4588981, 661509, 83313, '<td valign="top">Another creative entry. I haven''t enjoyed a challenge this much since "stupid gifts"!</td>', 'Another creative entry. I haven''t enjoyed a challenge this much since "stupid gifts"!', '2008-03-26 13:32:21.000000', NULL, 1),
(4588984, 661288, 83313, '<td valign="top">It helps them to forget their problems. However, their problem is that they drink too much.</td>', 'It helps them to forget their problems. However, their problem is that they drink too much.', '2008-03-26 13:33:56.000000', NULL, 1),
(4588986, 661505, 27373, '<td valign="top">Very well done, but you have way too much time on your hands to do this much in a 24 hour challenge  :)</td>', 'Very well done, but you have way too much time on your hands to do this much in a 24 hour challenge  :)', '2008-03-26 13:34:03.000000', NULL, 1),
