(4596804, 661267, 67697, '<td valign="top">So cute and what a great idea.  This works for me as an ancient peep!  (oops my kid just popped in and said "cool.  a dog made out of marshmallows" hehe)  Good luck!</td>', 'So cute and what a great idea.  This works for me as an ancient peep!  (oops my kid just popped in and said "cool.  a dog made out of marshmallows" hehe)  Good luck!', '2008-03-30 14:05:47.000000', NULL, 1),
(4596808, 661246, 67697, '<td valign="top">Very cute.  I love the soft focus on everything.  And then to have the peep pop out it that softness is perfect.  Good luck!</td>', 'Very cute.  I love the soft focus on everything.  And then to have the peep pop out it that softness is perfect.  Good luck!', '2008-03-30 14:06:52.000000', NULL, 1),
(4596817, 661202, 67697, '<td valign="top">This is a scream.  I saw this and my first thoughts went straight to the A-Team and Murdock yelling "Trash Bags!".  Love the jewelry and the hairdo.  So funny.  Good luck!</td>', 'This is a scream.  I saw this and my first thoughts went straight to the A-Team and Murdock yelling "Trash Bags!".  Love the jewelry and the hairdo.  So funny.  Good luck!', '2008-03-30 14:11:06.000000', NULL, 1),
(4596830, 661246, 1054, '<td valign="top">Not marking you down for it, but might "Just Born" have been a better title? They are, after all, the manufacturers of Peeps.</td>', 'Not marking you down for it, but might "Just Born" have been a better title? They are, after all, the manufacturers of Peeps.', '2008-03-30 14:20:01.000000', NULL, 1),
(4596854, 661487, 67697, '<td valign="top">This is a cute idea.  It''s like watching a bunch of sparrows hanging around.  You were so lucky to find flying peeps!  The Easter Bunny was good to you  :)</td>', 'This is a cute idea.  It''s like watching a bunch of sparrows hanging around.  You were so lucky to find flying peeps!  The Easter Bunny was good to you  :)', '2008-03-30 14:34:22.000000', NULL, 1),
